# Generated by build.py from recipe.yml for recipe imap-check-the-flags-an-app-left. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'order1.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Order 1 shipped`n`nYour first order is on its way.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'order2.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Order 2 shipped`n`nYour second order is on its way.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'spam.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: You have won a prize`n`nClick here to claim it.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'news.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Our autumn newsletter`n`nNew colours in store.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'shop@example.com:shoppass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "{order1,order2,spam,news}.eml" smtp://127.0.0.1:8080/example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 4 FLAGS" imap://127.0.0.1:8081/INBOX
curl.exe -sS -o "read#1.eml" -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=[1-2]"
curl.exe -sS -o NUL -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=3;SECTION=HEADER.FIELDS%20(SUBJECT)" --next -sS -o NUL -u ann@example.com:annpass -X "STORE 3 +FLAGS (\Deleted)" imap://127.0.0.1:8081/INBOX
try { curl.exe -u ann@example.com:annpass -X "FETCH 1:* FLAGS" imap://127.0.0.1:8081/INBOX } finally { Stop-Process $server0 }
